from pathlib import Path
import subprocess,json,hashlib,os
p=Path(__file__).parent;r=Path('/home/reinsirk/Atcoder_Env');h=p/'preload_root_size.hpp'
sha=lambda f:hashlib.sha256(f.read_bytes()).hexdigest()
ccs={'gcc':['/usr/bin/g++'],'clang':['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']}
sources=[r/'Verify/current/tests'/n for n in ['uf_reference_test.cpp','uf_exception_test.cpp','uf_merge_reference_test.cpp','uf_failed_merge_reference_test.cpp']]
rows=[]
def check(cc,src,skip,mode='default',flags=()):
 exe=p/f'preload-{cc}-{src.stem}-{skip}-{mode}'
 cmd=['taskset','-c','4',*ccs[cc],'-std=c++23','-O2',*flags,f'-DSIRKIT_UF_SOURCE="{h}"',str(src),'-o',str(exe)]
 if skip:cmd.insert(5,'-DSKIP_RUNTIME_CHECKS')
 a=subprocess.run(cmd,capture_output=True,text=True);assert a.returncode==0,(cmd,a.stderr)
 env=dict(os.environ,ASAN_OPTIONS='detect_leaks=0',UBSAN_OPTIONS='halt_on_error=1')
 b=subprocess.run(['taskset','-c','4',str(exe)],capture_output=True,text=True,env=env,timeout=120)
 assert b.returncode==0,(cmd,b.returncode,b.stdout,b.stderr)
 rows.append(dict(cc=cc,skip=skip,mode=mode,fixture=str(src),fixture_sha256=sha(src),header_sha256=sha(h),command=cmd,passed=True,stdout=b.stdout,stderr=b.stderr))
 (p/'preload-checks.json').write_text(json.dumps(dict(header=str(h),header_sha256=sha(h),results=rows),indent=2))
for cc in ccs:
 for skip in [False,True]:
  for src in sources:check(cc,src,skip)
  print(cc,skip,'4 default fixtures PASS',flush=True)
for skip in [False,True]:
 for src in sources[2:]:check('gcc',src,skip,'native',['-march=native'])
print('gcc native PASS',flush=True)
for skip in [False,True]:
 for src in [sources[0],sources[3]]:check('gcc',src,skip,'asan_ubsan',['-g','-fsanitize=address,undefined','-fno-omit-frame-pointer'])
print('preload ALL PASS',len(rows),sha(h),flush=True)

