// SPDX-License-Identifier: CC0-1.0
#include HEADER
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <ctime>
#include <numeric>
#include <random>
struct Op{int type,a,b;};
extern "C" std::uint64_t run_queries(UnionFind&,const std::vector<Op>&);
extern "C" std::uint64_t run_mixed(UnionFind&,const std::vector<Op>&);
struct Reference{std::vector<int>p,s;int components;explicit Reference(int n):p(n),s(n,1),components(n){std::iota(p.begin(),p.end(),0);}int root(int a){int r=a;while(p[r]!=r)r=p[r];while(p[a]!=a){int b=p[a];p[a]=r;a=b;}return r;}bool merge(int a,int b){a=root(a);b=root(b);if(a==b)return false;if(s[a]<s[b])std::swap(a,b);p[b]=a;s[a]+=s[b];--components;return true;}bool same(int a,int b){return root(a)==root(b);}};
std::uint64_t now(){return static_cast<std::uint64_t>(std::clock())*1000000000/CLOCKS_PER_SEC;}
int main(int argc,char**argv){if(argc!=3)return 2;int n=std::atoi(argv[1]),shape=std::atoi(argv[2]);std::mt19937 rng(891473);UnionFind uf(n);Reference ref(n);auto merge=[&](int a,int b){if(uf.merge(a,b)!=ref.merge(a,b))std::abort();};
if(shape==0||shape==1||shape==3||shape==9||shape==10||shape==14||shape==15){for(int step=1;step<n;step*=2)for(int i=0;i+step<n;i+=step*2)merge(i,i+step);}else if(shape==2||shape==13||shape==18||shape==19){for(int i=1;i<n;++i)merge(0,i);}else if(shape==4||shape==5||shape==6||shape==16||shape==17){int group=shape==4?4:(shape==5||shape==16)?16:1024;for(int i=0;i<n;i+=group)for(int j=i+1;j<std::min(n,i+group);++j)merge(i,j);}
std::vector<Op>ops;const int q=n<1024?200000:1000000;ops.reserve(q);for(int i=0;i<q;++i){int a=int(rng()%n),b=int(rng()%n),type=1;if(shape==1||shape==8)b=a;if(shape==2)b=0;if(shape==9)a=0;if(shape==10)b=(a^1)%n;if(shape==11)type=int(rng()&1);if(shape>=12)type=0;if(shape==15)b=a;if(shape==16)b=(a/16)*16;if(shape==17)b=((a^1)%n);if(shape==18)b=0;if(shape==19)a=0;ops.push_back({type,a,b});}
std::uint64_t expected=0;for(auto op:ops)expected+=op.type?ref.same(op.a,op.b):ref.merge(op.a,op.b);const auto start=now();std::uint64_t sum=shape<11?run_queries(uf,ops):run_mixed(uf,ops);const auto elapsed=now()-start;if(sum!=expected||uf.component_count()!=ref.components)return 4;for(int i=0;i<n;i+=std::max(1,n/1000))if(uf.root(i)!=ref.root(i)||uf.size(i)!=ref.s[ref.root(i)])return 5;std::printf("%ju %ju\n",static_cast<std::uintmax_t>(elapsed),static_cast<std::uintmax_t>(sum));}

