struct Op{int type,a,b;};
extern "C" [[gnu::noinline,gnu::aligned(64)]] std::uint64_t run_mixed(UnionFind& uf,const std::vector<Op>& ops){std::uint64_t sum=0;for(auto op:ops)sum+=op.type?uf.same(op.a,op.b):uf.merge(op.a,op.b);return sum;}

